/**
 * The branching tree generator.
 *
 * Produces the component list for a broadleaf tree: a trunk, a set of
 * branches at two levels, leaf clumps at the tips, and exposed roots.
 *
 * It produces components rather than geometry. Each component is then
 * generated by its own part generator, which is what lets one branch be
 * regenerated without touching the rest of the tree.
 */

import * as THREE from 'three'
import {z} from 'zod'
import type {GeneratedComponent, PropGenerator} from '../shared/generator-types'
import {IDENTITY_TRANSFORM, type Transform} from '../shared/component-types'
import {hashSeed, randomRange} from '../shared/random'
import {
    choiceSchema,
    numberSchema,
    validateParameters,
    type ParameterSpec,
    type ValidationResult,
} from '../shared/parameters'
import {buildTrunkSpine, SPINE_POINT_COUNT, type BendAmount} from './components/trunk'
import {buildBranchSpine, BRANCH_POINTS, type BranchParameters} from './components/branch'
import {buildRootSpine, ROOT_POINTS} from './components/root'
import type {FoliageShape} from './components/foliage-cluster'

export type TreeParameters = {
    readonly height: number
    readonly trunkRadius: number
    readonly bend: BendAmount
    readonly twist: number
    readonly taper: number
    readonly branchCount: number
    readonly branchLevels: number
    readonly branchLength: number
    readonly branchAngle: number
    readonly foliageCount: number
    readonly foliageSize: number
    readonly foliageShape: FoliageShape
    readonly rootCount: number
    readonly asymmetry: number
}

const HEIGHT = {
    kind: 'number', key: 'height', label: 'Height', help: 'How tall the tree is.',
    min: 1, max: 12, step: 0.1, unit: 'm', default: 4.2,
} as const satisfies ParameterSpec

const THICKNESS = {
    kind: 'number', key: 'trunkRadius', label: 'Thickness', help: 'How thick the trunk is.',
    min: 0.05, max: 1.2, step: 0.01, unit: 'm', default: 0.32,
} as const satisfies ParameterSpec

const BEND = {
    kind: 'choice', key: 'bend', label: 'Bend', help: 'How much the trunk curves.',
    options: [
        {value: 'straight', label: 'Straight'},
        {value: 'curved', label: 'Curved'},
        {value: 'very-curved', label: 'Very curved'},
    ],
    default: 'curved',
} as const satisfies ParameterSpec

const TWIST = {
    kind: 'number', key: 'twist', label: 'Twist', help: 'How much the trunk spirals.',
    min: -180, max: 180, step: 5, unit: 'deg', default: 0,
} as const satisfies ParameterSpec

const TAPER = {
    kind: 'number', key: 'taper', label: 'Taper', help: 'How much the trunk narrows toward the top.',
    min: 0.2, max: 1, step: 0.05, default: 0.55,
} as const satisfies ParameterSpec

const BRANCHES = {
    kind: 'number', key: 'branchCount', label: 'Branches', help: 'How many branches the tree has.',
    min: 0, max: 40, step: 1, unit: 'count', default: 12,
} as const satisfies ParameterSpec

const BRANCH_LENGTH = {
    kind: 'number', key: 'branchLength', label: 'Branch length', help: 'How long the branches are.',
    min: 0.3, max: 6, step: 0.1, unit: 'm', default: 2.6,
} as const satisfies ParameterSpec

const LEAVES = {
    kind: 'number', key: 'foliageCount', label: 'Leaves', help: 'How many clumps of leaves.',
    min: 0, max: 60, step: 1, unit: 'count', default: 20,
} as const satisfies ParameterSpec

const LEAF_SIZE = {
    kind: 'number', key: 'foliageSize', label: 'Leaf size', help: 'How big each clump is.',
    min: 0.2, max: 2.5, step: 0.05, unit: 'm', default: 0.6,
} as const satisfies ParameterSpec

const LEAF_SHAPE = {
    kind: 'choice', key: 'foliageShape', label: 'Leaf shape',
    options: [
        {value: 'round', label: 'Round'},
        {value: 'oval', label: 'Oval'},
        {value: 'flat', label: 'Flat'},
        {value: 'tall', label: 'Tall'},
        {value: 'irregular', label: 'Irregular'},
        {value: 'layered', label: 'Layered'},
    ],
    default: 'round',
} as const satisfies ParameterSpec

const ROOTS = {
    kind: 'number', key: 'rootCount', label: 'Roots', help: 'How many roots spread out from the base.',
    min: 0, max: 12, step: 1, unit: 'count', default: 6,
} as const satisfies ParameterSpec

export const treeParameterSpecs: readonly ParameterSpec[] = [
    HEIGHT,
    THICKNESS,
    TAPER,
    BEND,
    TWIST,
    BRANCHES,
    BRANCH_LENGTH,
    LEAVES,
    LEAF_SIZE,
    LEAF_SHAPE,
    ROOTS,
]

const treeSchema = z.object({
    height: numberSchema(HEIGHT),
    trunkRadius: numberSchema(THICKNESS),
    bend: choiceSchema(BEND),
    twist: numberSchema(TWIST),
    taper: numberSchema(TAPER),
    branchCount: numberSchema(BRANCHES),
    branchLevels: z.number().int().min(1).max(4).catch(2),
    branchLength: numberSchema(BRANCH_LENGTH),
    branchAngle: z.number().min(0).max(90).catch(45),
    foliageCount: numberSchema(LEAVES),
    foliageSize: numberSchema(LEAF_SIZE),
    foliageShape: choiceSchema(LEAF_SHAPE),
    rootCount: numberSchema(ROOTS),
    asymmetry: z.number().min(0).max(1).catch(0.3),
})

/** The angle between successive branches, in radians. */
const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5))

/** Where branches start, as a fraction of the trunk height. */
const BRANCH_START = 0.32
const BRANCH_END = 0.94

/** The curve a branch follows, used to place things that grow out of it. */
type BranchCurve = {
    readonly length: number
    readonly baseRadius: number
    readonly tipRadius: number
    readonly bend: number
    readonly curl: number
    readonly twist: number
}

/** The local shape of a branch at a point along its length. */
function branchLocalPoint(parameters: BranchCurve, t: number): THREE.Vector3 {
    return new THREE.Vector3(
        parameters.length * t,
        parameters.length * parameters.bend * t * t,
        parameters.length * parameters.curl * t * t,
    )
}

function branchLocalTangent(parameters: BranchCurve, t: number): THREE.Vector3 {
    const a = branchLocalPoint(parameters, Math.max(t - 0.05, 0))
    const b = branchLocalPoint(parameters, Math.min(t + 0.05, 1))

    return b.sub(a).normalize()
}

/** The rotation that turns the local positive X axis along a direction. */
function rotationTowards(direction: THREE.Vector3): Transform['rotation'] {
    const quaternion = new THREE.Quaternion().setFromUnitVectors(
        new THREE.Vector3(1, 0, 0),
        direction.clone().normalize(),
    )

    const euler = new THREE.Euler().setFromQuaternion(quaternion, 'YXZ')

    return [euler.x, euler.y, euler.z]
}

function transformOf(position: THREE.Vector3, rotation: Transform['rotation']): Transform {
    return {
        position: [position.x, position.y, position.z],
        rotation,
        scale: [1, 1, 1],
    }
}

interface BranchNode {
    readonly id: string
    readonly parentId: string
    readonly worldStart: THREE.Vector3
    readonly quaternion: THREE.Quaternion
    readonly direction: THREE.Vector3
    readonly parameters: BranchCurve
    readonly depth: number
}

export const branchingTreeGenerator: PropGenerator<TreeParameters> = {
    id: 'branching-tree',
    version: 1,
    label: 'Broadleaf tree',
    parameters: treeParameterSpecs,

    createDefaultParameters(): TreeParameters {
        return {
            height: HEIGHT.default,
            trunkRadius: THICKNESS.default,
            bend: BEND.default,
            twist: TWIST.default,
            taper: TAPER.default,
            branchCount: BRANCHES.default,
            branchLevels: 2,
            branchLength: BRANCH_LENGTH.default,
            branchAngle: 45,
            foliageCount: LEAVES.default,
            foliageSize: LEAF_SIZE.default,
            foliageShape: LEAF_SHAPE.default,
            rootCount: ROOTS.default,
            asymmetry: 0.3,
        }
    },

    validate(parameters: unknown): ValidationResult<TreeParameters> {
        return validateParameters(treeSchema, parameters, this.createDefaultParameters())
    },

    generate(parameters, context): readonly GeneratedComponent[] {
        const components: GeneratedComponent[] = []
        const random = context.random
        const seed = context.seed

        // --- Trunk -------------------------------------------------------
        const azimuth = randomRange(random, 0, Math.PI * 2)
        const wobble = randomRange(random, -0.15, 0.15) * parameters.asymmetry
        const spine = buildTrunkSpine(parameters.bend, parameters.height, azimuth, wobble)

        const trunkId = 'cmp-trunk-0'
        components.push({
            id: trunkId,
            type: 'trunk',
            generatorId: 'trunk',
            generatorVersion: 1,
            parentId: null,
            transform: IDENTITY_TRANSFORM,
            parameters: {
                height: parameters.height,
                baseRadius: parameters.trunkRadius,
                taper: parameters.taper,
                bend: parameters.bend,
                twist: parameters.twist,
                controlPoints: SPINE_POINT_COUNT,
                spine,
                leanAzimuth: azimuth,
                leanWobble: wobble,
            },
            seed: hashSeed(seed, 0),
            slot: 'trunk',
        })

        // The trunk's spine, sampled so branches can sit on it.
        const trunkPoints = spine.map((point) => {
            const twist = THREE.MathUtils.degToRad(parameters.twist)
            const vector = new THREE.Vector3(point.x, point.t * parameters.height, point.z)

            if (twist !== 0) {
                vector.applyAxisAngle(new THREE.Vector3(0, 1, 0), twist * point.t)
            }

            return vector
        })

        const trunkAt = (t: number): THREE.Vector3 => {
            const scaled = THREE.MathUtils.clamp(t, 0, 1) * (trunkPoints.length - 1)
            const index = Math.min(Math.floor(scaled), trunkPoints.length - 2)
            const fraction = scaled - index

            return trunkPoints[index].clone().lerp(trunkPoints[index + 1], fraction)
        }

        // --- Branches ----------------------------------------------------
        const branchCount = Math.round(parameters.branchCount)
        const levels = Math.round(parameters.branchLevels)
        const nodes: BranchNode[] = []
        const up = new THREE.Vector3(0, 1, 0)

        for (let i = 0; i < branchCount; i++) {
            const progress = branchCount === 1 ? 0.6 : i / (branchCount - 1)
            const jitter = randomRange(random, -0.08, 0.08) * parameters.asymmetry
            const t = THREE.MathUtils.clamp(
                BRANCH_START + (BRANCH_END - BRANCH_START) * progress + jitter,
                0.15,
                0.98,
            )

            const angle = azimuth + i * GOLDEN_ANGLE + randomRange(random, -0.3, 0.3)

            const outward = new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle))
            const tilt = THREE.MathUtils.degToRad(
                parameters.branchAngle + randomRange(random, -12, 12),
            )

            const direction = outward
                .clone()
                .multiplyScalar(Math.cos(tilt))
                .add(up.clone().multiplyScalar(Math.sin(tilt)))
                .normalize()

            const trunkRadiusHere = parameters.trunkRadius * (1 - t * 0.55)
            const baseRadius = Math.max(trunkRadiusHere * randomRange(random, 0.22, 0.34), 0.012)

            const length =
                parameters.branchLength * randomRange(random, 0.7, 1.15) * (1.15 - t * 0.4)
            const bend = randomRange(random, 0.25, 0.7)
            const curl = randomRange(random, -0.25, 0.25)

            const branchParameters: BranchParameters = {
                length,
                baseRadius,
                tipRadius: Math.max(baseRadius * 0.3, 0.006),
                bend,
                curl,
                twist: randomRange(random, -10, 10),
                controlPoints: BRANCH_POINTS,
                spine: buildBranchSpine(bend, curl, length),
            }

            const id = `cmp-branch-${nodes.length}`
            const worldStart = trunkAt(t)

            nodes.push({
                id,
                parentId: trunkId,
                worldStart,
                quaternion: new THREE.Quaternion().setFromUnitVectors(
                    new THREE.Vector3(1, 0, 0),
                    direction,
                ),
                direction,
                parameters: branchParameters,
                depth: 0,
            })

            components.push({
                id,
                type: 'branch',
                generatorId: 'branch',
                generatorVersion: 1,
                parentId: trunkId,
                transform: transformOf(worldStart, rotationTowards(direction)),
                parameters: branchParameters,
                seed: hashSeed(seed, nodes.length),
                slot: `branch-${nodes.length}`,
            })
        }

        // Child branches hang off the branches above them.
        for (let depth = 1; depth < levels; depth++) {
            const parents = nodes.filter((node) => node.depth === depth - 1)
            const children: BranchNode[] = []

            for (const parent of parents) {
                // The child count is derived from the parent's position rather
                // than drawn at random, so the tree keeps the same size when
                // only the variation changes.
                const childCount = 2 + (nodes.indexOf(parent) % 2)

                for (let c = 0; c < childCount; c++) {
                    const along = randomRange(random, 0.45, 0.95)
                    const local = branchLocalPoint(parent.parameters, along)
                    const worldStart = local.applyQuaternion(parent.quaternion).add(parent.worldStart)

                    const tangent = branchLocalTangent(parent.parameters, along)
                        .applyQuaternion(parent.quaternion)
                        .normalize()

                    const sideways = new THREE.Vector3(-tangent.z, 0, tangent.x)
                    if (sideways.lengthSq() < 1e-6) {
                        sideways.set(1, 0, 0)
                    }
                    sideways.normalize()

                    const swing = randomRange(random, 0.5, 1.1) * (c % 2 === 0 ? 1 : -1)

                    const direction = tangent
                        .clone()
                        .multiplyScalar(0.75)
                        .add(sideways.multiplyScalar(Math.sin(swing) * 0.85))
                        .add(up.clone().multiplyScalar(0.3))
                        .normalize()

                    const baseRadius = Math.max(parent.parameters.baseRadius * 0.6, 0.008)

                    const childLength = parent.parameters.length * randomRange(random, 0.5, 0.8)
                    const childBend = randomRange(random, 0.3, 0.8)
                    const childCurl = randomRange(random, -0.3, 0.3)

                    const branchParameters: BranchParameters = {
                        length: childLength,
                        baseRadius,
                        tipRadius: Math.max(baseRadius * 0.3, 0.005),
                        bend: childBend,
                        curl: childCurl,
                        twist: randomRange(random, -12, 12),
                        controlPoints: BRANCH_POINTS,
                        spine: buildBranchSpine(childBend, childCurl, childLength),
                    }

                    const id = `cmp-branch-${nodes.length + children.length}`
                    const quaternion = new THREE.Quaternion().setFromUnitVectors(
                        new THREE.Vector3(1, 0, 0),
                        direction,
                    )

                    children.push({
                        id,
                        parentId: parent.id,
                        worldStart,
                        quaternion,
                        direction,
                        parameters: branchParameters,
                        depth,
                    })

                    components.push({
                        id,
                        type: 'branch',
                        generatorId: 'branch',
                        generatorVersion: 1,
                        parentId: parent.id,
                        transform: transformOf(worldStart, rotationTowards(direction)),
                        parameters: branchParameters,
                        seed: hashSeed(seed, nodes.length + children.length),
                        slot: `branch-${nodes.length + children.length}`,
                    })
                }
            }

            nodes.push(...children)
        }

        // --- Leaves ------------------------------------------------------
        const tips = nodes.filter((node) => node.depth >= levels - 1)
        const foliageCount = Math.round(parameters.foliageCount)

        if (tips.length > 0 && foliageCount > 0) {
            for (let i = 0; i < foliageCount; i++) {
                const node = tips[i % tips.length]
                const along = 0.75 + (i / foliageCount) * 0.25
                const local = branchLocalPoint(node.parameters, Math.min(along, 1))
                const world = local.applyQuaternion(node.quaternion).add(node.worldStart)

                const id = `cmp-foliage-${i}`

                components.push({
                    id,
                    type: 'foliage-cluster',
                    generatorId: 'foliage-cluster',
                    generatorVersion: 1,
                    parentId: node.id,
                    transform: transformOf(
                        world,
                        [
                            randomRange(random, -0.3, 0.3),
                            randomRange(random, 0, Math.PI * 2),
                            randomRange(random, -0.3, 0.3),
                        ],
                    ),
                    parameters: {
                        shape: parameters.foliageShape,
                        size: parameters.foliageSize * randomRange(random, 0.75, 1.25),
                        roughness: 0.35,
                    },
                    seed: hashSeed(seed, 1000 + i),
                    slot: `foliage-${i}`,
                })
            }
        }

        // --- Roots -------------------------------------------------------
        const rootCount = Math.round(parameters.rootCount)

        for (let i = 0; i < rootCount; i++) {
            const angle = azimuth + (i / Math.max(rootCount, 1)) * Math.PI * 2 + randomRange(random, -0.3, 0.3)
            const outward = new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle))
            const direction = outward
                .clone()
                .multiplyScalar(0.92)
                .add(up.clone().multiplyScalar(-0.12))
                .normalize()

            const baseRadius = Math.max(parameters.trunkRadius * randomRange(random, 0.25, 0.4), 0.02)
            const rootLength = parameters.trunkRadius * randomRange(random, 3, 5.5)
            const drop = randomRange(random, 0.15, 0.5)
            const curl = randomRange(random, -0.35, 0.35)

            components.push({
                id: `cmp-root-${i}`,
                type: 'root',
                generatorId: 'root',
                generatorVersion: 1,
                parentId: trunkId,
                transform: transformOf(new THREE.Vector3(0, 0.06, 0), rotationTowards(direction)),
                parameters: {
                    length: rootLength,
                    baseRadius,
                    tipRadius: Math.max(baseRadius * 0.18, 0.006),
                    drop,
                    curl,
                    controlPoints: ROOT_POINTS,
                    spine: buildRootSpine(drop, curl, rootLength),
                },
                seed: hashSeed(seed, 2000 + i),
                slot: `root-${i}`,
            })
        }

        return components
    },
}
